#include "engine.hpp"
#include <cmath>
#include <iostream>
using namespace uaa;
void check(bool b,const char* m){if(!b)throw std::runtime_error(m);}
void prepare(Engine& e){e.createBase("ISS",50,14);e.ensureLocations();e.state["money"]=100000000LL;e.rentLocation("nasa");e.rentLocation("roscosmos");e.rentISS(12);e.state["leases"]["nasa"]=100000.;e.state["leases"]["roscosmos"]=100000.;e.state["weatherOverrides"]={{"florida",{{"risk",0},{"until",100000.}}},{"baikonur",{{"risk",0},{"until",100000.}}}};}
int main(int argc,char** argv){try{
 check(argc==3,"Expected data and temporary directory");Engine e(argv[1],argv[2]);prepare(e);check(e.permanentISSCrew().size()==7&&e.state["issPermanentCrew"].size()==7,"Seven permanent ISS crew exist independently of hired astronauts");check(e.state["astronauts"].empty(),"Station crew do not occupy Houston recruitment roster");e.state["issPermanentCrew"]=Json::array();e.ensureLocations();check(e.state["issPermanentCrew"].size()==7,"Permanent crew cannot be removed");check(e.issStatus()["technicians"]==3&&e.issStatus()["scientists"]==2,"Technical and scientific teams are distinct");e.advance(24);check(e.state["iss"]["systems"]["hull"].get<double>()<100&&e.state["iss"]["ageHours"]==24.,"Age wears the station");check(e.state["iss"]["scienceHours"].get<double>()>0,"Scientists work during normal operations");
 check(e.damageISS("lifeSupport",70,"DEBRIS").ok,"Debris can damage life support");check(e.issStatus()["emergency"]==true&&e.issStatus()["researchEnabled"]==false&&e.issStatus()["resourceMultiplier"]==.35,"Life-support failure enforces essential-only mode");double research=e.state["iss"]["scienceHours"],technical=e.state["iss"]["maintenanceHours"];check(e.repairISS("lifeSupport").ok,"Technicians can repair in emergency");e.advance(12);check(e.state["iss"]["scienceHours"]==research&&e.state["iss"]["maintenanceHours"].get<double>()>technical,"Scientists pause while technicians continue");check(std::abs(e.issStatus()["repairHoursLeft"].get<double>()-12)<1e-8,"Repair ETA decreases");e.save(2);Engine pendingRepair(argv[1],argv[2]);check(pendingRepair.load(2).ok&&std::abs(pendingRepair.issStatus()["repairHoursLeft"].get<double>()-12)<1e-8,"Ongoing repair and ETA survive reload");e.advance(12);check(e.state["iss"]["repair"].is_null()&&!e.issStatus()["emergency"].get<bool>(),"Repair completes and normal operations resume");e.advance(1);check(e.state["iss"]["scienceHours"].get<double>()>research,"Scientific work resumes after repair");
 e.state["iss"]["nextImpact"]=e.state["hours"].get<double>()+1.;auto incidentCount=e.state["iss"]["incidents"].size();e.advance(1);check(e.state["iss"]["incidents"].size()>incidentCount,"Meteoroids or debris cause persistent incidents");
 // The visible moving systems and launch forecast share one deterministic offline field.
 {Engine climate(argv[1],fs::path(argv[2])/"climate");auto systems=climate.weatherSystems(0.);check(systems==climate.weatherSystems(0.),"Paused weather systems are stable");check(systems!=climate.weatherSystems(24.),"Weather moves with game hours");for(const auto& sys:systems){double lon=sys["lon"],lat=sys["lat"];auto center=climate.weatherAt(lon,lat,0.);check(center["risk"].get<int>()>=55,"Visible vortex has elevated launch risk");check(std::abs(center["risk"].get<int>()-climate.weatherAt(lon,lat,.01)["risk"].get<int>())<=1,"Weather changes continuously");check(center==climate.weatherAt(lon+360,lat,0.),"Weather wraps across world longitude");}for(const auto& site:{"florida","baikonur","kourou"}){auto w=climate.launchWeather(site,24.);check(w["safe"].get<bool>()==(w["risk"].get<int>()<60),"Launch safety matches displayed weather");}}
 // Weather postpones supplies; the last safe launch overrides weather with a reserve for the flight.
 Engine weather(argv[1],fs::path(argv[2])/"weather");prepare(weather);weather.state["weatherOverrides"]["florida"]["risk"]=95;weather.state["weatherOverrides"]["baikonur"]["risk"]=95;check(weather.launchWeather("florida",0.)["risk"]==weather.weatherAt(-80.6042,28.6084,0.)["risk"],"Map and launch decision use identical meteorological cell");check(weather.sendISSSupplies("florida").ok,"Reserve regular supply rocket");auto paid=weather.state["money"];weather.advance(1);check(weather.state["iss"]["shipments"][0]["launch"].is_null()&&weather.state["iss"]["shipments"][0]["status"]=="weatherDelay","Bad weather postpones launch");check(weather.state["money"]==paid,"Weather checks never charge the rocket twice");weather.state["iss"]["stocks"]["oxygen"]=10.;weather.state["iss"]["stocks"]["water"]=10.;weather.state["iss"]["stocks"]["food"]=10.;weather.advance(1);auto& ship=weather.state["iss"]["shipments"][0];check(!ship["launch"].is_null()&&ship["forced"]==true,"Critical supplies trigger necessary launch despite bad weather");check(ship["arrival"].get<double>()<weather.state["hours"].get<double>()+weather.issStatus()["survivalHours"].get<double>(),"Critical launch includes transit time before supplies run out");weather.advance(48);check(ship["delivered"]==true&&weather.state["iss"]["stocks"]["water"].get<double>()>100,"Emergency supplies arrive and replenish life support");
 Engine regular(argv[1],fs::path(argv[2])/"regular");prepare(regular);check(regular.state["iss"]["supplyPlan"]["enabled"]==true&&regular.state["iss"]["supplyPlan"]["intervalDays"]==14,"Renting ISS enables fortnightly regular supply flights");regular.advance(16*24);check(!regular.state["iss"]["shipments"].empty()&&regular.state["iss"]["shipments"][0]["delivered"]==true,"Automatic scheduled shipment launches and arrives");check(regular.state["iss"]["stocks"]["food"].get<double>()>300,"Regular supplies maintain crew reserves");regular.save(1);Engine loaded(argv[1],fs::path(argv[2])/"regular");check(loaded.load(1).ok&&loaded.state["iss"]==regular.state["iss"]&&loaded.state["issPermanentCrew"].size()==7,"Damage, teams, logistics, modules and mandatory crew survive save/load");
 auto broken=readJson(regular.userDir/"save-1.json");broken["iss"]["systems"]["lifeSupport"]=-1.;writeJson(regular.userDir/"save-3.json",broken);auto before=loaded.state;check(!loaded.load(3).ok&&loaded.state==before,"Malformed station data is rejected without replacing the campaign");
 Engine clear(argv[1],fs::path(argv[2])/"clear");prepare(clear);clear.state["weatherOverrides"]["florida"]["risk"]=95;check(clear.sendISSSupplies("florida").ok,"Book weather-delayed flight");clear.advance(1);clear.state["weatherOverrides"]["florida"]["risk"]=0;clear.advance(6);check(!clear.state["iss"]["shipments"][0]["launch"].is_null()&&clear.state["iss"]["shipments"][0]["forced"]==false,"Delayed rocket launches normally after weather improves");
 Engine alternate(argv[1],fs::path(argv[2])/"alternate");prepare(alternate);alternate.state["weatherOverrides"]["florida"]["risk"]=95;alternate.state["iss"]["supplyPlan"]["nextAt"]=0.;alternate.advance(1);check(alternate.state["iss"]["shipments"][0]["source"]=="baikonur"&&!alternate.state["iss"]["shipments"][0]["launch"].is_null(),"Weather chooses the available alternative launch site");
 auto legacy=readJson(regular.userDir/"save-1.json");legacy.erase("iss");legacy.erase("issPermanentCrew");writeJson(regular.userDir/"save-2.json",legacy);check(loaded.load(2).ok&&loaded.state["issPermanentCrew"].size()==7&&loaded.state.contains("iss"),"Older saves migrate to permanent crew and station systems");
 std::cout<<"PASS: permanent crew, age, system damage, emergency limits, separate teams, repairs, map-driven weather delays, critical launches, regular supplies and save/load\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
